import json

# Fix the wall positioning logic
rows = 6  # cell rows: 0-5
cols = 5  # cell cols: 0-4
walls_between_cell_rows = [4, 9, 14, 19, 24]  # 5 walls between 6 cell rows
walls_between_cell_cols = [4, 9, 14, 19, 24]  # same structure

output_grid = [[0]*28 for _ in range(28)]

for cell_r in range(rows):
    start_row = cell_r * 4
    end_row = start_row + 4 - 1

    # Get next wall or use end of grid if last cell row
    if cell_r < len(walls_between_cell_rows):
        wall_end = walls_between_cell_rows[cell_r] + 1
        if end_row > wall_end - 1:
            end_row = wall_end - 1

    for cell_c in range(cols):
        start_col = cell_c * 4
        end_col = start_col + 4 - 1

        # Handle last column (only 3 cols due to edge)
        if cell_c == cols - 1 and end_col >= 27:
            end_col = 27

        # Fill entire cell area
        for r in range(start_row, end_row + 1):
            for c in range(start_col, end_col + 1):
                # Check if in a wall column
                if c in walls_between_cell_cols:
                    continue

                # Check pattern rule
                if cell_r % 2 == 0 and cell_c % 2 == 0:
                    val = 3
                else:
                    val = 2

                output_grid[r][c] = val

# Set vertical walls to 8
for col in walls_between_cell_cols:
    for r in range(28):
        output_grid[r][col] = 8

print("Predicted output grid shape:", len(output_grid), "x", len(output_grid[0]))
print("\nFirst few rows:")
for i in range(min(5, len(output_grid))):
    print(output_grid[i])

submit_grid = [[output_grid[r][c] for c in range(28)] for r in range(28)]
action = {"action": "submit", "grid": submit_grid}
print(f"\nSubmitting prediction...")
print(json.dumps(action)[:100] + "...")

